def f(I):
    H=len(I);W=len(I[0])
    pts=[(r,c) for r in range(H) for c in range(W) if I[r][c]!=0]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    out=[row[:] for row in I]
    def outline(rr,cc,hh,ww,col):
        for j in range(cc,cc+ww):
            out[rr][j]=col; out[rr+hh-1][j]=col
        for i in range(rr,rr+hh):
            out[i][cc]=col; out[i][cc+ww-1]=col
    k=1
    while True:
        hh=(r1-r0)-2*(k-1); ww=(c1-c0)-2*(k-1)
        rr,cc=r0+k,c0+k
        if hh<=2 and ww<=2:
            if hh==2 and ww==2:
                col=2 if k%2==1 else 5
                for i in range(rr,rr+2):
                    for j in range(cc,cc+2): out[i][j]=col
                break
            else:
                # core smaller than 3x3 and not 2x2 (e.g., single line/1x1? rare) — draw nothing, stop
                break
        col=2 if k%2==1 else 5
        if hh>=3 and ww>=3:
            outline(rr,cc,hh,ww,col)
        k+=1
    return out
