# Search for a repeat unit with majority-vote denoising for each demo pair.
def best_tile(i,maxp=25):
    H,W=i.shape
    best=[]
    for p in range(2,maxp+1):
        for q in range(2,maxp+1):
            # build tile by voting
            votes=[[Counter() for _ in range(q)] for _ in range(p)]
            for r in range(H):
                for c in range(W):
                    votes[r%p][c%q]+= [int(i[r,c])]
            T=[[votes[a][b].most_common(1)[0][0] for b in range(q)] for a in range(p)]
            if p*q<=max(p*p+p,q*q+q)+10: 
                mism=sum(1 for r in range(H) for c in range(W) if i[r,c]!=T[r%p][c%q])
                score=mism/(H*W)
                best.append((score,p,q,T))
    return sorted(best)[:3]
